def lattice(frame):
    return tuple(
        tuple(int(frame[y][x]) for x in COL_ANCHORS)
        for y in ROW_ANCHORS
    )


def fast_shift(before, after):
    a, b = lattice(before), lattice(after)
    scored = []
    for bands in range(10):
        hits = sum(
            a[i][j] == b[i + bands][j]
            for i in range(10 - bands)
            for j in range(8)
        )
